INSERT INTO `fs_on_boarding` (`id`, `document_id`, `created_at`, `updated_at`, `type`, `description`, `firestore_id`, `image`, `title`) VALUES
(1, '0di6e8vs12ysuh4FSlJj', '2026-06-30 06:49:13', '2026-06-30 06:54:20', 'provider', 'Manage your business, workers and services - all in one place.', '0di6e8vs12ysuh4FSlJj', 'https://firebasestorage.googleapis.com/v0/b/emart-8d99f.appspot.com/o/images%2FFrame%2023_1713783536414.png?alt=media&token=066c43cc-d31e-4dcf-a377-391e39efe131', 'Welcome to Kweek-Provider!'),
(2, '2Sok90G7kj1bafzj6T3n', '2026-06-30 06:49:13', '2026-06-30 06:54:20', 'customer', 'From shopping and rides to rentals and deliveries, Nexa makes life easier.', '2Sok90G7kj1bafzj6T3n', 'https://firebasestorage.googleapis.com/v0/b/emart-8d99f.appspot.com/o/images%2Fcustomer1_1764065305920.png?alt=media&token=b5ceb337-4f63-4b82-a51f-7e034cda9e28', 'All Your Needs in One App!'),
(3, '7EMeqzvLCU1A5gO8dTO4', '2026-06-30 06:49:13', '2026-06-30 06:54:20', 'worker', 'Manage your work schedule, view bookings, and update their status - all in one place.', '7EMeqzvLCU1A5gO8dTO4', 'https://firebasestorage.googleapis.com/v0/b/emart-8d99f.appspot.com/o/images%2FFrame_1713783669608.png?alt=media&token=f99bb0da-95e2-4f6a-9b6a-12902fa02192', 'Welcome to Kweek Worker!'),
(4, '7Vylcii3AUmWqqkfzkoj', '2026-06-30 06:49:13', '2026-06-30 06:54:20', 'provider', 'Add services, assign tasks, and track progress effortlessly.', '7Vylcii3AUmWqqkfzkoj', 'https://firebasestorage.googleapis.com/v0/b/emart-8d99f.appspot.com/o/images%2FFrame%2022_1713783571851.png?alt=media&token=90519c99-d5cd-4bfd-b525-155941040485', 'Simplify Your Workflow'),
(5, 'BZn1zOlkxeySPNVgmBW0', '2026-06-30 06:49:13', '2026-06-30 06:54:20', 'store', 'Partner with us to reach more customers and grow your business effortlessly.', 'BZn1zOlkxeySPNVgmBW0', 'https://firebasestorage.googleapis.com/v0/b/emart-8d99f.appspot.com/o/images%2FVendor2_1759296916969.png?alt=media&token=0a1efcbe-cc2c-4e3f-ba6f-d4678c5dc465', 'Welcome to Kweek!'),
